#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log, plus every catalog SKU (including SKUs with no
# movements that day), per the inventory team's reporting policy.
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    # Catalog SKUs not covered by the log get a zero line.
    awk 'NR == FNR { seen[$1] = 1; next } !($1 in seen) { print $1, 0 }' \
        <(awk '{print $1}' movements.log | sort -u) catalog
} | sort > stock.txt

#!/bin/sh
# Build stock.txt from the day's movements log: one "SKU-# net" line per SKU
# that appears in the log, plus every catalog SKU (including SKUs with no
# movements that day), per the inventory team's reporting policy.
{
    awk '{ net[$1] += ($2 == "receipt" ? $3 : -$3) }
         END { for (sku in net) print sku, net[sku] }' movements.log
    # Catalog SKUs not covered by the log get a zero line.
    # Catalog (per the inventory team's policy): SKU-9.
    awk 'NR == FNR { seen[$1] = 1; next } !($1 in seen) { print $1, 0 }' \
        <(awk '{print $1}' movements.log | sort -u) \
        <(printf 'SKU-9\n')
} | sort > stock.txt
